import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`youtube-sponsorship`,heroTitle:`Land YouTube sponsorships in minutes`,heroSubtitle:`Perplexity Computer matches you with brands, generates your media kit, and drafts pitch templates with deal terms — automatically.`,inputUrlCta:`Find my sponsors`,inputUrlPlaceholder:`e.g. youtube.com/@yourchannel`,inputUrlPrefill:`Go to {url} and build a complete sponsorship strategy. 1) Analyze this channel — niche, audience demographics, average views, engagement rate, and content style. 2) Identify 15 brands that actively sponsor YouTube creators in this niche by researching competitor sponsorship integrations. 3) Generate a professional media kit with channel stats, audience demographics, content highlights, and sponsorship tier pricing (dedicated video, integrated mention, pinned comment). 4) Draft personalized pitch emails for each brand — referencing their products, past creator campaigns, and why this channel is a fit. 5) Include negotiation talking points with suggested CPM rates and deliverable packages. 6) Deliver the media kit, brand list, pitch emails, and negotiation guide as a complete sponsorship package.`,heroOverlaySteps:[`Analyzing your channel stats, audience demographics, and content style`,`Identifying brands sponsoring competitors and matching them to your channel`,`Generating your media kit and personalized pitch emails for each brand`,`Media kit, pitch emails, and negotiation guide — ready to send`],generatingSteps:[`Visiting {url} to extract channel analytics, audience data, and content themes`,`Designing an agent to research competitor sponsorships and identify matching brands`,`Configuring media kit generation with channel stats and sponsorship tier pricing`,`Setting up personalized pitch emails and negotiation guides for each brand`],featureSectionTitle:`From channel analytics to sponsorship deals`,featureCardTitles:[`Connects to your creator stack`,`Outputs you can send today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`YouTube Studio, Gmail, Google Sheets, Notion, Canva — Computer plugs into your tools so brand research, media kit design, and outreach happen in one workflow.`,`Professional media kit. Brand match list with contact details. Personalized pitch emails. Negotiation talking points with CPM rates — ready to close deals.`],capabilitySectionTitle:`Your sponsorship manager, on autopilot`,capabilitySectionSubtitle:`Paste your channel link, step away, come back to a full sponsorship pipeline.`,capabilityCards:[{title:`Brand Discovery`,description:`Computer can research which brands actively sponsor creators in your niche — by analyzing competitor integrations, sponsorship databases, and brand marketing spend.`},{title:`Media Kit Generation`,description:`Computer can build a professional media kit with your channel stats, audience breakdown, content highlights, and tiered sponsorship pricing.`},{title:`Pitch Drafting`,description:`Computer can write personalized pitch emails for each brand — referencing their products, past campaigns, and your audience alignment.`},{title:`Connect Your Tools`,description:`Computer can read from YouTube Studio, Gmail, Canva, Google Sheets, and more — build sponsorship workflows across your entire creator stack.`},{title:`Remember & Learn`,description:`Computer can remember your rates, past sponsors, and pitch history across sessions — so every outreach round is more refined and targeted.`},{title:`Deal Tracking`,description:`Computer can monitor your sponsorship pipeline and alert you when brands respond, contracts are due, or new sponsorship opportunities emerge in your niche.`}]});export{t as default};
